// Typst compilation in the browser (WebAssembly, typst.ts in a Web Worker).
// Classic script: shares the page's global scope with the other editor scripts (see editor_page.rs for the load order).
//
// The compiler and its fonts are served by NeoLeaf (static/typst/, generated by scripts/fetch_typst_assets.py); the packages a document imports
// (@preview/...) are downloaded by the browser from packages.typst.org. Nothing of the project is sent anywhere.

// The page asks for this script as compile-typst.js?v=<build>: the worker and its library get the same version, so a worker kept in a cache
// (the CDN keeps static files for hours) is never mixed with a newer page.
const TYPST_QUERY = (function () {
  try {
    const m = document.currentScript && /[?&]v=([^&#]+)/.exec(document.currentScript.src);
    return m ? '?v=' + m[1] : '';
  } catch (_) {
    return '';
  }
})();

let typstWorker = null;
let typstCallId = 0;
const typstCalls = new Map();   // id -> { resolve }

function isTypstFile(path) {
  return /\.typ$/i.test(String(path || ''));
}

function getTypstWorker() {
  if (typstWorker) return typstWorker;
  typstWorker = new Worker('/static/js/typst-worker.js' + TYPST_QUERY);
  typstWorker.onmessage = function (e) {
    const msg = e.data || {};
    if (msg.type === 'compiled') {
      const call = typstCalls.get(msg.id);
      if (call) { typstCalls.delete(msg.id); call.resolve(msg); }
    } else if (msg.type === 'error') {
      // the compiler could not start: fail every compilation that is waiting
      for (const [id, call] of typstCalls) { typstCalls.delete(id); call.resolve({ id: id, pdf: null, diagnostics: [], error: msg.message }); }
    }
  };
  typstWorker.onerror = function (e) {
    for (const [id, call] of typstCalls) { typstCalls.delete(id); call.resolve({ id: id, pdf: null, diagnostics: [], error: (e && e.message) || 'the worker stopped' }); }
    typstWorker = null;
  };
  return typstWorker;
}

// Starts loading the compiler (a few MB, once per browser) before the first compilation, e.g. when a .typ file is opened.
function warmUpTypst() {
  try { getTypstWorker().postMessage({ type: 'warmup' }); } catch (_) {}
}

function runTypst(files, main) {
  return new Promise(resolve => {
    const id = ++typstCallId;
    typstCalls.set(id, { resolve });
    getTypstWorker().postMessage({ type: 'compile', id: id, main: main, files: files });
  });
}

// The log shown in the Logs tab: the compiler's messages, then the timings.
function typstLog(diagnostics, mainFile, timing) {
  const lines = ['Typst (WebAssembly)'];
  for (const d of diagnostics) {
    const where = d.file ? d.file + (d.line ? ':' + d.line + (d.column ? ':' + d.column : '') : '') : '';
    lines.push((d.severity || 'error') + ': ' + d.message + (where ? '\n  --> ' + where : ''));
  }
  if (!diagnostics.length) lines.push('no messages');
  lines.push('\n===== ' + mainFile + ' =====\n' + timing);
  return lines.join('\n');
}

// Compiles the project with Typst; returns what renderCompileResult shows.
async function compileWithTypst() {
  updateStatus('saving', 'Gathering the project files...');
  const sw = stopwatch();
  const { files, main, texmfOnly } = await gatherProject();
  sw.lap('project');

  if (!isTypstFile(main)) throw new Error(T('This project has no Typst file (.typ).'));

  updateStatus('saving', T('Compiling with Typst (WebAssembly)...'));
  const payload = [];
  for (const [path, content] of files) {
    if (path.startsWith('.neoleaf/') || (texmfOnly && texmfOnly.has(path))) continue;   // LaTeX packages and project data are not for Typst
    payload.push(typeof content === 'string' ? { path: path, text: content } : { path: path, bytes: content });
  }
  const out = await runTypst(payload, main);
  sw.lap('compilation');
  if (out.error) throw new Error(T('The Typst compiler could not be loaded: {0}', out.error));

  const diagnostics = (out.diagnostics || []).map(d => ({
    line: d.line,
    column: d.column,
    endLine: d.endLine,
    endColumn: d.endColumn,
    file: d.file,
    is_error: d.severity !== 'warning',
    message: d.message + (d.file && d.file !== main ? ' (' + d.file + ')' : '')
  }));
  const pdfBytes = out.pdf || null;
  const log = typstLog(out.diagnostics || [], main, sw.summary());
  console.info('[Typst compilation]', sw.summary());

  if (pdfBytes && pdfBytes.length) {
    hasPdf = true;
    updatePdfEmpty();
    if (window.PdfView) {
      PdfView.show(pdfBytes, null).catch(() => {});
      PdfView.setBusy(false);
    }
    switchTab('pdf');
    updateStatus('saved', T('Compiled successfully (Typst WebAssembly)'));
  } else {
    updateStatus('error', 'Compilation error (Typst)');
    switchTab('logs');
  }
  return { success: !!(pdfBytes && pdfBytes.length), pdfBytes: pdfBytes, synctexBytes: null, log: log, diagnostics: diagnostics, mainFile: main };
}

// With a Typst project open, loads the compiler in the background so the first compilation does not wait for it.
window.addEventListener('editor-ready', function () {
  const main = String((typeof projectConfig !== 'undefined' && projectConfig && projectConfig.mainFile) || '');
  if (isTypstFile(main) || isTypstFile(typeof currentFileId === 'string' ? currentFileId : '')) setTimeout(warmUpTypst, 1500);
});

// Compiles with Typst and shows the result.
async function compileAndShowTypst() {
  try {
    const res = await compileWithTypst();
    renderCompileResult(res);
    if (res.success) persistLastPdf(res, 'wasm-typst');
  } catch (err) {
    console.error('Typst compilation error:', err);
    renderCompileResult({
      success: false,
      log: T('Error running the Typst WebAssembly compiler: {0}', err.message),
      diagnostics: [{ line: 1, message: err.message, is_error: true }]
    });
  }
}
